#pragma once
// Android DeskClock 4.2.2 presentation adapted to the NavPlus app viewport.
// Icons/dials are the original AOSP resources; layout and touch share bounds.
struct DeskClockHit {Placement bounds;bettergps_deskclock::Action action;int arg=0;};
struct DeskClockCanvas {
 std::vector<uint8_t>* pixels;std::vector<DeskClockHit> hits;int clipTop=63,clipBottom=483;
 void fill(Placement r,COLORREF c,unsigned alpha=255){if(!pixels)return;for(int y=std::max(clipTop,r.y);y<std::min(clipBottom,r.y+r.h);++y)for(int x=std::max(0,r.x);x<std::min(900,r.x+r.w);++x){auto* p=pixels->data()+(y*900+x)*4;p[0]=uint8_t((GetBValue(c)*alpha+p[0]*(255-alpha))/255);p[1]=uint8_t((GetGValue(c)*alpha+p[1]*(255-alpha))/255);p[2]=uint8_t((GetRValue(c)*alpha+p[2]*(255-alpha))/255);p[3]=255;}}
 void text(const std::string& value,Placement r,int size=22,int weight=FW_MEDIUM,COLORREF color=RGB(255,255,255),bool center=true){
  if(!pixels||value.empty()||r.w<=0||r.h<=0)return;
  static std::unordered_map<std::string,CopilotClockGlyph> cache;const auto key=std::to_string(size)+":"+std::to_string(weight)+":"+value;
  auto it=cache.find(key);if(it==cache.end()){if(cache.size()>=96)cache.clear();it=cache.emplace(key,copilot_clock_glyph(value,size,weight)).first;}
  const auto& g=it->second;if(!g.width||!g.height)return;const double scale=std::min({1.,double(r.w)/g.width,double(r.h)/g.height});const int w=std::max(1,int(g.width*scale)),h=std::max(1,int(g.height*scale));auto colored=g.pixels;
  for(size_t i=0;i<colored.size();i+=4){colored[i]=GetBValue(color);colored[i+1]=GetGValue(color);colored[i+2]=GetRValue(color);}
  overlay_blit(*pixels,colored,g.width,g.height,{r.x+(center?(r.w-w)/2:0),r.y+(r.h-h)/2,w,h},900,544);
 }
 void icon(const char* name,Placement r){if(!pixels)return;const auto& im=copilot_image(std::string("deskclock/")+name+".dds");if(!im.width||!im.height)return;const double s=std::min(double(r.w)/im.width,double(r.h)/im.height);const int w=int(im.width*s),h=int(im.height*s);overlay_blit(*pixels,im.pixels,im.width,im.height,{r.x+(r.w-w)/2,r.y+(r.h-h)/2,w,h},900,544);}
 void hand(const char* name,Placement r,double angle){if(!pixels)return;const auto& im=copilot_image(std::string("deskclock/")+name+".dds");if(!im.width||!im.height)return;const double co=std::cos(angle),si=std::sin(angle);for(int y=0;y<r.h;++y)for(int x=0;x<r.w;++x){const int xx=r.x+x,yy=r.y+y;if(xx<0||xx>=900||yy<112||yy>=442)continue;const double dx=(x+.5-r.w*.5)*im.width/r.w,dy=(y+.5-r.h*.5)*im.height/r.h;const int sx=int(std::floor(co*dx+si*dy+im.width*.5)),sy=int(std::floor(-si*dx+co*dy+im.height*.5));if(sx<0||sy<0||sx>=int(im.width)||sy>=int(im.height))continue;const auto* source=im.pixels.data()+(sy*im.width+sx)*4;auto* dst=pixels->data()+(yy*900+xx)*4;for(int k=0;k<3;++k)dst[k]=uint8_t((source[k]*source[3]+dst[k]*(255-source[3])+127)/255);dst[3]=255;}}
 void target(Placement r,bettergps_deskclock::Action action,int arg=0){hits.push_back({r,action,arg});}
 void button(std::string label,Placement r,bettergps_deskclock::Action a,int arg=0,bool selected=false){fill(r,selected?RGB(115,42,42):RGB(43,46,49));text(label,r,20);target(r,a,arg);}
 void imageButton(const char* image,Placement r,bettergps_deskclock::Action a,int arg=0){icon(image,{r.x+(r.w-30)/2,r.y+(r.h-30)/2,30,30});target(r,a,arg);}
 void ring(int cx,int cy,int radius,double progress){if(!pixels)return;const double pi=3.141592653589793;for(int y=cy-radius-3;y<=cy+radius+3;++y)for(int x=cx-radius-3;x<=cx+radius+3;++x){if(x<0||x>=900||y<111||y>=441)continue;const double d=std::hypot(double(x-cx),double(y-cy));const double coverage=std::clamp(2.6-std::abs(d-radius),0.,1.);if(!coverage)continue;double angle=std::atan2(double(x-cx),double(cy-y));if(angle<0)angle+=2*pi;const bool red=angle<=std::clamp(progress,0.,1.)*2*pi;const COLORREF c=red?RGB(255,68,68):RGB(94,96,98);auto* p=pixels->data()+(y*900+x)*4;p[0]=uint8_t(GetBValue(c)*coverage+p[0]*(1-coverage));p[1]=uint8_t(GetGValue(c)*coverage+p[1]*(1-coverage));p[2]=uint8_t(GetRValue(c)*coverage+p[2]*(1-coverage));p[3]=255;}}
};
static std::string desk_duration(int64_t ms,bool fractions=false){const bool minus=ms<0;ms=std::abs(ms);const auto sec=ms/1000;char out[64];if(sec>=3600)std::snprintf(out,sizeof(out),"%s%lld:%02lld:%02lld",minus?"-":"",sec/3600,sec/60%60,sec%60);else std::snprintf(out,sizeof(out),"%s%lld:%02lld",minus?"-":"",sec/60,sec%60);std::string result=out;if(fractions){std::snprintf(out,sizeof(out),".%02lld",ms/10%100);result+=out;}return result;}
static std::string desk_alarm_time(int minute,bool h24){const int h=minute/60;char s[32];std::snprintf(s,sizeof(s),h24?"%02d:%02d":"%d:%02d",h24?h:(h%12?h%12:12),minute%60);return s;}
static std::string desk_days(int days){if(!days)return "Once";if(days==127)return "Every day";static const char* names[]={"Mon","Tue","Wed","Thu","Fri","Sat","Sun"};std::string s;for(int i=0;i<7;++i)if(days&(1<<i)){if(!s.empty())s+=" ";s+=names[i];}return s;}
static int64_t desk_city_time(int index,int64_t utc){
 if(index<0||size_t(index)>=bettergps_deskclock::cities.size()||utc<0)return std::numeric_limits<int64_t>::min();
 static std::map<std::wstring,DYNAMIC_TIME_ZONE_INFORMATION> zones;if(zones.empty())for(DWORD i=0;;++i){DYNAMIC_TIME_ZONE_INFORMATION z{};if(EnumDynamicTimeZoneInformation(i,&z)!=ERROR_SUCCESS)break;zones.emplace(z.TimeZoneKeyName,z);}
 const auto it=zones.find(bettergps_deskclock::cities[index].windows);if(it==zones.end())return std::numeric_limits<int64_t>::min();SYSTEMTIME now{},local{};GetSystemTime(&now);if(!SystemTimeToTzSpecificLocalTimeEx(&it->second,&now,&local))return std::numeric_limits<int64_t>::min();FILETIME a{},b{};if(!SystemTimeToFileTime(&now,&a)||!SystemTimeToFileTime(&local,&b))return std::numeric_limits<int64_t>::min();ULARGE_INTEGER x{},y{};x.LowPart=a.dwLowDateTime;x.HighPart=a.dwHighDateTime;y.LowPart=b.dwLowDateTime;y.HighPart=b.dwHighDateTime;return utc+(int64_t(y.QuadPart)-int64_t(x.QuadPart))/600000000LL;
}
static std::vector<int> desk_city_filter(const std::string& query){std::vector<int> ids;auto q=query;for(char& c:q)c=char(std::tolower(static_cast<unsigned char>(c)));for(size_t i=0;i<bettergps_deskclock::cities.size();++i){std::string name=bettergps_deskclock::cities[i].name;for(char& c:name)c=char(std::tolower(static_cast<unsigned char>(c)));if(name.find(q)!=std::string::npos)ids.push_back(int(i));}return ids;}
