static std::vector<uint8_t> copilot_clock_layer(){std::vector<uint8_t> pixels(900*544*4,0);auto view=bettergps_deskclock::clock.view();view.game=copilot_minutes();view.utcGame=view.game<0||!(gameTimezoneState.load()&1)?-1:int64_t(g_gameTimeMinutes.load())+g_multiplayerTimeOffset.load()-gameTimezoneReferenceMinutes.load();desk_clock_layout(&pixels,view);if(view.screen==bettergps_deskclock::Screen::Main&&view.tabAt&&view.now>=view.tabAt&&view.now-view.tabAt<220&&view.previousTab!=view.tab){auto old=view;old.tab=view.previousTab;old.settingTimer=false;std::vector<uint8_t> before(900*544*4,0);desk_clock_layout(&before,old);const auto current=pixels;const double t=double(view.now-view.tabAt)/220,progress=t*t*(3-2*t);const int shift=int(900*progress),direction=view.tab>view.previousTab?1:-1;for(int y=112;y<483;++y)for(int x=0;x<900;++x){const int previousX=x+direction*shift,newX=x-direction*(900-shift);const auto at=(y*900+x)*4;if(previousX>=0&&previousX<900)memcpy(pixels.data()+at,before.data()+(y*900+previousX)*4,4);else if(newX>=0&&newX<900)memcpy(pixels.data()+at,current.data()+(y*900+newX)*4,4);}}return pixels;}
static void copilot_clock_alert(std::vector<uint8_t>& pixels,const OverlaySettings& config){const auto v=bettergps_deskclock::clock.view();if(v.alerts.empty())return;std::vector<uint8_t> layer(900*544*4,0);desk_clock_alert(&layer,v);overlay_blit(pixels,layer,900,544,config.items[1],900,544);}
static bool copilot_clock_hit(float x,float y,bool alertOnly=false){
 auto view=bettergps_deskclock::clock.view();const auto buttons=!view.alerts.empty()?desk_clock_alert(nullptr,view):alertOnly?std::vector<DeskClockHit>{}:desk_clock_layout(nullptr,view);
 for(auto i=buttons.rbegin();i!=buttons.rend();++i)if(x>=i->bounds.x&&y>=i->bounds.y&&x<i->bounds.x+i->bounds.w&&y<i->bounds.y+i->bounds.h){bettergps_deskclock::clock.act(i->action,i->arg);return true;}return !view.alerts.empty();
}
